const log=document.getElementById('log');
function request(w,data,expect){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Timeout')),30000);w.onmessage=({data:d})=>{if(d.type==='progress')return;clearTimeout(timer);if(d.type==='error'&&expect!=='error')reject(Error(d.message));else if(d.type!==expect)reject(Error(`Expected ${expect}, got ${d.type}`));else resolve(d);};w.onerror=()=>{clearTimeout(timer);reject(Error('Worker error'));};w.postMessage(data);});}
async function image(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#245b43';x.fillRect(w/4,h/4,w/2,h/2);return new Promise(resolve=>c.toBlob(resolve,'image/png'));}
document.getElementById('start').onclick=async e=>{e.target.disabled=true;log.textContent='';let worker;
try{for(const [w,h] of [[320,480],[480,320]]){worker=new Worker('/processor.js',{type:'module'});const loaded=await request(worker,{action:'load',file:await image(w,h)},'loaded');if(loaded.meta.width!==w)throw Error('Wrong source dimensions');const result=await request(worker,{action:'process',requirements:{width:200,height:230,format:'image/jpeg',min:0,max:100,unit:1000},rotation:1,mode:'fit',x:50,y:50,zoom:1},'result');if(result.checks.some(c=>!c.pass))throw Error('Output checks failed');const b=await createImageBitmap(result.blob);if(b.width!==200||b.height!==230)throw Error('Wrong output dimensions');b.close();log.textContent+=`PASS: ${w}×${h} load, rotate, encode, verify\n`;await request(worker,{action:'process',requirements:{width:200,height:230,format:'image/png',min:0,max:.001,unit:1000},rotation:0,mode:'crop',x:50,y:50,zoom:1},'error');log.textContent+='PASS: impossible cap returns error\n';worker.terminate();}
worker=new Worker('/processor.js',{type:'module'});await request(worker,{action:'load',file:new Blob(['broken'])},'error');log.textContent+='PASS: corrupt/unsupported file rejected\n';log.textContent+='Smoke checks complete. Device-specific checks are still required.';
}catch(err){log.textContent+='FAIL: '+err.message;}finally{worker?.terminate();e.target.disabled=false;}};
